CREATE TABLE agg_actions ( id text PRIMARY KEY CHECK (trim(id) <> ''), client_token text CHECK (client_token IS NULL OR trim(client_token) <> ''), kind text NOT NULL CHECK (kind IN ('triage', 'status-request', 'session', 'preference')), verb text NOT NULL, object_ref text NOT NULL CHECK (trim(object_ref) <> ''), target_ref text, session_id text, session_source text, payload TEXT NOT NULL CHECK (json_type(payload) = 'object'), author TEXT NOT NULL CHECK ( json_type(author) = 'object' AND coalesce(json_extract(author, '$.kind') IN ('drew', 'muse', 'agent'), 0) AND nullif(trim(json_extract(author, '$.id')), '') IS NOT NULL AND nullif(trim(json_extract(author, '$.label')), '') IS NOT NULL ), created_at TEXT NOT NULL, state text NOT NULL DEFAULT 'new' CHECK (state IN ('new', 'applied', 'rejected', 'superseded')), applied_at TEXT, applied_by_run text, result_note text, supersedes_action_id text REFERENCES agg_actions(id) ON DELETE RESTRICT, duplicate_of_action_id text REFERENCES agg_actions(id) ON DELETE RESTRICT, CONSTRAINT agg_actions_verb_for_kind_check CHECK ( (kind = 'triage' AND verb IN ( 'acknowledge', 'snooze', 'escalate', 'de-escalate', 'answer', 'delegate', 'dismiss', 'approve-proposal', 'reject-proposal', 'mark-done', 'restore' )) OR (kind = 'status-request' AND verb = 'request-status') OR (kind = 'session' AND verb IN ('poke', 'answer', 'stop')) OR (kind = 'preference' AND verb IN ( 'set-delegation-default', 'set-needs-order', 'save-view', 'rename-view', 'delete-view', 'set-default-view' )) ), CONSTRAINT agg_actions_result_timestamp_check CHECK ( (state = 'applied' AND applied_at IS NOT NULL) OR (state = 'rejected' AND (applied_at IS NOT NULL OR duplicate_of_action_id IS NOT NULL)) OR (state = 'new' AND applied_at IS NULL) OR state = 'superseded' ), CONSTRAINT agg_actions_not_self_superseded_check CHECK ( supersedes_action_id IS NULL OR supersedes_action_id <> id ), CONSTRAINT agg_actions_not_self_duplicate_check CHECK ( duplicate_of_action_id IS NULL OR duplicate_of_action_id <> id ) );
CREATE UNIQUE INDEX agg_actions_client_token_uq ON agg_actions (client_token) WHERE client_token IS NOT NULL;
CREATE INDEX agg_actions_state_created_at_idx ON agg_actions (state, created_at DESC);
CREATE INDEX agg_actions_object_created_at_idx ON agg_actions (object_ref, created_at DESC);
CREATE TABLE shared_events ( id text PRIMARY KEY CHECK (trim(id) <> ''), event_at TEXT NOT NULL, ingested_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')), event_at_raw text CHECK (event_at_raw IS NULL OR trim(event_at_raw) <> ''), ingested_at_raw text CHECK (ingested_at_raw IS NULL OR trim(ingested_at_raw) <> ''), actor text NOT NULL CHECK (trim(actor) <> ''), kind text NOT NULL CHECK (trim(kind) <> ''), ref text NOT NULL CHECK (trim(ref) <> ''), summary text NOT NULL, attribution TEXT NOT NULL DEFAULT '{"confidence":"unknown","asserted":false}' CHECK ( json_type(attribution) = 'object' AND coalesce(json_extract(attribution, '$.confidence') IN ('authenticated', 'pre-sso', 'unknown'), 0) AND coalesce(json_type(attribution, '$.asserted') IN ('true', 'false'), 0) AND (json_extract(attribution, '$.confidence') <> 'authenticated' OR json_extract(attribution, '$.asserted') = 1) ), source TEXT NOT NULL DEFAULT '{"identity":"pm-stack/aggregator"}' CHECK ( json_type(source) = 'object' AND nullif(trim(json_extract(source, '$.identity')), '') IS NOT NULL ), attribution_raw text CHECK ( attribution_raw IS NULL OR json_type(attribution_raw) = 'object' ), source_raw text CHECK ( source_raw IS NULL OR json_type(source_raw) = 'object' ), corrects_event_id text, migrated_from_version INTEGER CHECK (migrated_from_version IS NULL OR migrated_from_version = 1), prev_hash text NOT NULL CHECK ((length(prev_hash) = 64 AND prev_hash NOT GLOB '*[^0-9a-f]*')), hash text NOT NULL CHECK ((length(hash) = 64 AND hash NOT GLOB '*[^0-9a-f]*')), action_id text REFERENCES agg_actions(id) ON DELETE RESTRICT, idempotency_key text CHECK (idempotency_key IS NULL OR trim(idempotency_key) <> ''), CONSTRAINT shared_events_action_link_check CHECK ( ( kind IN ('action-applied', 'action-rejected') AND action_id IS NULL AND idempotency_key IS NULL ) OR ( kind IN ('action-applied', 'action-rejected') AND action_id IS NOT NULL AND idempotency_key IS NOT NULL AND idempotency_key = 'action-result:' || action_id ) OR (kind NOT IN ('action-applied', 'action-rejected') AND action_id IS NULL) ) );
CREATE UNIQUE INDEX shared_events_idempotency_key_uq ON shared_events (idempotency_key) WHERE idempotency_key IS NOT NULL;
CREATE UNIQUE INDEX shared_events_action_outcome_uq ON shared_events (action_id) WHERE action_id IS NOT NULL;
CREATE INDEX shared_events_event_at_idx ON shared_events (event_at DESC);
CREATE INDEX shared_events_kind_ref_event_at_idx ON shared_events (kind, ref, event_at DESC);
